-		nbcon_cpu_emergency_enter();
-		print_lockdep_off("BUG: MAX_LOCKDEP_ENTRIES too low and folio_pool exhausted!");
-		dump_stack();
-		nbcon_cpu_emergency_exit();
-		return NULL;
+	p = folio_pool_alloc_type(&lockdep_pool, struct lock_list, GFP_ATOMIC);
+	if (p) {
